type Message = { role: "user" | "assistant"; content: any; attachment?: { name: string; type: string } };
type HistoryItem = { id: string; title: string; data: { messages?: Message[] }; pinned?: boolean; archived?: boolean; updated_at?: string; };
function messageText(value: any) { return Array.isArray(value) ? value.find((part: any) => part.type === "text")?.text || "Imagen adjunta" : String(value || ""); }
function escapeHtml(value: string) { return value.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function renderMessage(text: any) {
  const plain = messageText(text); const lines = plain.split("\n"); const output: string[] = []; let inCode = false; let codeLang = ""; let codeLines: string[] = [];
  const inline = (value: string) => escapeHtml(value).replace(/`([^`]+)`/g,"<code>$1</code>").replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/\*([^*\n]+)\*/g,"<em>$1</em>").replace(/\$\$([^$\n]+)\$\$/g,"<span class=\"math-block\">$1</span>").replace(/\$([^$\n]+)\$/g,"<span class=\"math-inline\">$1</span>");
  for (let i=0;i<lines.length;i++) { const line=lines[i]; if (line.startsWith("```")) { if (inCode) { output.push(`<pre><code class="language-${escapeHtml(codeLang)}">${escapeHtml(codeLines.join("\n"))}</code></pre>`); codeLines=[]; inCode=false; codeLang=""; } else { inCode=true; codeLang=line.slice(3).trim() || "text"; } continue; } if (inCode) { codeLines.push(line); continue; }
    if (/^\s*\|.*\|\s*$/.test(line) && i+1<lines.length && /^\s*\|?\s*:?-{2,}/.test(lines[i+1])) { const headers=line.split("|").slice(1,-1).map((v: string)=>`<th>${inline(v.trim())}</th>`).join(""); i++; const rows=[]; while(i+1<lines.length && /^\s*\|.*\|\s*$/.test(lines[i+1])) { i++; rows.push(`<tr>${lines[i].split("|").slice(1,-1).map((v: string)=>`<td>${inline(v.trim())}</td>`).join("")}</tr>`); } output.push(`<div class="table-scroll"><table><thead><tr>${headers}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`); continue; }
    if (/^#{1,3}\s+/.test(line)) { const level=(line.match(/^#+/)||["#"])[0].length; output.push(`<h${level+1}>${inline(line.replace(/^#{1,3}\s+/,""))}</h${level+1}>`); continue; }
    if (/^\s*[-*]\s+/.test(line)) { output.push(`<li>${inline(line.replace(/^\s*[-*]\s+/,""))}</li>`); continue; }
    if (/^\s*\d+[.)]\s+/.test(line)) { output.push(`<li class="ordered-item">${inline(line.replace(/^\s*\d+[.)]\s+/,""))}</li>`); continue; }
    if (!line.trim()) { output.push("<div class=\"message-break\"></div>"); continue; } output.push(`<p>${inline(line)}</p>`);
  }
  if (inCode) output.push(`<pre><code class="language-${escapeHtml(codeLang)}">${escapeHtml(codeLines.join("\n"))}</code></pre>`);
  const image = Array.isArray(text) ? text.find((part: any) => part.type === "image_url")?.image_url?.url : "";
  return (image ? `<img class="message-image" loading="lazy" decoding="async" src="${String(image).replace(/"/g,"&quot;")}" alt="Imagen adjunta"/>` : "") + output.join("");
}
function renderStreaming(text: any) { return escapeHtml(messageText(text)).replace(/\n/g,"<br/>"); }

