  const [email, setEmail] = useState(""); const [tier, setTier] = useState("free"); const [copiedMessage, setCopiedMessage] = useState<number | null>(null); const [modelMenuOpen, setModelMenuOpen] = useState(false); const [billingOpen, setBillingOpen] = useState(false); const [expiresAt, setExpiresAt] = useState(0); const [privacyOpen, setPrivacyOpen] = useState(false); const [purchasePlan, setPurchasePlan] = useState(""); const [ratedMessages, setRatedMessages] = useState<Record<number,string>>({}); const [speakingMessage, setSpeakingMessage] = useState<number | null>(null); const [composerMenuOpen, setComposerMenuOpen] = useState(false); const [webSearchMode, setWebSearchMode] = useState(false); const [customSuggestions, setCustomSuggestions] = useState(suggestions); const [creditsSpent, setCreditsSpent] = useState(0); const [creditsLimit, setCreditsLimit] = useState(5000); const [accountMenuOpen, setAccountMenuOpen] = useState(false); const [settingsOpen, setSettingsOpen] = useState(false); const [compactMode, setCompactMode] = useState(false); const [animations, setAnimations] = useState(true); const [enterToSend, setEnterToSend] = useState(true); const [defaultModel, setDefaultModel] = useState("auto"); const [voiceLanguage, setVoiceLanguage] = useState("es-ES"); const [activeModel, setActiveModel] = useState("auto"); const [settingsCategory, setSettingsCategory] = useState("appearance"); const [density, setDensity] = useState("comfortable"); const [fontScale, setFontScale] = useState("normal"); const [highContrast, setHighContrast] = useState(false); const [dataTraining, setDataTraining] = useState(false); const [accentColor, setAccentColor] = useState("#8B78FF"); const [historyOpen, setHistoryOpen] = useState(true); const [historyMenu, setHistoryMenu] = useState<string | null>(null); const [renameId, setRenameId] = useState<string | null>(null); const [renameValue, setRenameValue] = useState(""); const [deleteId, setDeleteId] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]); const [text, setText] = useState("");
  const [busy, setBusy] = useState(false); const abortRef = useRef<AbortController | null>(null); const [generationStatus, setGenerationStatus] = useState("Preparando respuesta…"); const [retryText, setRetryText] = useState(""); const [retryBase, setRetryBase] = useState<Message[]>([]); const [libraryOpen, setLibraryOpen] = useState(false); const [imageStudioOpen, setImageStudioOpen] = useState(false); const [imagePrompt, setImagePrompt] = useState(""); const [imageReference, setImageReference] = useState<File | null>(null); const [imageRatio, setImageRatio] = useState("1:1"); const [imageStyle, setImageStyle] = useState("Auto"); const [imageQuality, setImageQuality] = useState("Estándar"); const [scheduleOpen, setScheduleOpen] = useState(false); const [scheduleFilter, setScheduleFilter] = useState("all"); const [scheduleFormOpen, setScheduleFormOpen] = useState(false); const [scheduleTask, setScheduleTask] = useState(""); const [scheduleDate, setScheduleDate] = useState(""); const [scheduleFrequency, setScheduleFrequency] = useState("Una vez"); const [schedules, setSchedules] = useState<any[]>([]); const [libraryView, setLibraryView] = useState<"grid"|"list">("grid"); const [libraryQuery, setLibraryQuery] = useState(""); const [libraryFilter, setLibraryFilter] = useState("all"); const [librarySort, setLibrarySort] = useState("recent"); const [selectedLibrary, setSelectedLibrary] = useState<string[]>([]); const [historyQuery, setHistoryQuery] = useState(""); const [listening, setListening] = useState(false); const recognitionRef = useRef<any>(null); const [sidebarCollapsed, setSidebarCollapsed] = useState(false); const [sidebarAnimating, setSidebarAnimating] = useState(false); const [file, setFile] = useState<File | null>(null); const [error, setError] = useState(""); const [accountOpen, setAccountOpen] = useState(false); const [history, setHistory] = useState<HistoryItem[]>([]); const [conversationId, setConversationId] = useState(() => crypto.randomUUID());
  useEffect(() => { try { setSchedules(JSON.parse(localStorage.getItem("ainslup-schedules") || "[]")); } catch {} try { const saved = JSON.parse(localStorage.getItem("ainslup-preferences") || "{}"); setCompactMode(Boolean(saved.compactMode)); setAnimations(saved.animations !== false); setEnterToSend(saved.enterToSend !== false); setDefaultModel(saved.defaultModel || "auto"); setVoiceLanguage(saved.voiceLanguage || "es-ES"); setCustomSuggestions(saved.customSuggestions || suggestions); setActiveModel(saved.activeModel || "auto"); setDensity(saved.density || "comfortable"); setFontScale(saved.fontScale || "normal"); setHighContrast(Boolean(saved.highContrast)); setDataTraining(Boolean(saved.dataTraining)); setAccentColor(saved.accentColor || "#8B78FF"); } catch {} }, []);
  function savePreference(key: string, value: unknown) { const saved = JSON.parse(localStorage.getItem("ainslup-preferences") || "{}"); const next = { ...saved, [key]: value }; localStorage.setItem("ainslup-preferences", JSON.stringify(next)); }
  useEffect(() => { const closeOnEscape=(event: KeyboardEvent)=>{ if(event.key!=="Escape") return; setModelMenuOpen(false); setComposerMenuOpen(false); setAccountMenuOpen(false); setHistoryMenu(null); setLibraryOpen(false); setImageStudioOpen(false); setScheduleOpen(false); setBillingOpen(false); setPrivacyOpen(false); setSettingsOpen(false); setAccountOpen(false); setRenameId(null); setDeleteId(null); }; window.addEventListener("keydown",closeOnEscape); let alive = true; async function load() { if (!supabase) return; const { data } = await supabase.auth.getSession(); if (!alive) return; if (!data.session?.user) { window.location.href = "/login"; return; } setEmail(data.session.user.email || ""); const r = await fetch(`${EDGE}/me`, { headers: { Authorization: `Bearer ${data.session.access_token}` } }); if (r.ok && alive) { const d = await r.json(); setTier(d.tier || "free"); setExpiresAt(Number(d.expires_at || 0)); setCreditsSpent(Number(d.credits_spent || 0)); setCreditsLimit(Number(d.credits_limit || 5000)); } } load(); if (!supabase) return; loadHistory(); const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => { if (!session && alive) window.location.href = "/login"; }); return () => { alive = false; abortRef.current?.abort(); window.removeEventListener("keydown",closeOnEscape); listener.subscription.unsubscribe(); }; }, []);
  async function saveConversation(next: Message[]) { if (!supabase || !next.length) return; const user = (await supabase.auth.getUser()).data.user; if (!user) return; const first = next.find(m => m.role === "user"); const rawTitle = typeof first?.content === "string" ? first.content : first?.attachment?.name || "Archivo adjunto"; const title = rawTitle.slice(0, 48); await supabase.from("conversations").upsert({ id: conversationId, uid: user.id, title, data: { messages: next }, updated_at: new Date().toISOString() }); }
  async function loadConversation(item: HistoryItem) { setConversationId(item.id); setMessages(item.data?.messages || []); setError(""); setHistoryMenu(null); }
  async function updateConversation(id: string, changes: Record<string, unknown>) { if (!supabase) return; const { error: updateError } = await supabase.from("conversations").update(changes).eq("id", id); if (updateError) { setError(updateError.message); return; } setHistory(items => items.map(item => item.id === id ? { ...item, ...changes } : item)); setHistoryMenu(null); }
  async function renameConversation() { if (!renameId || !renameValue.trim()) return; await updateConversation(renameId, { title: renameValue.trim() }); setRenameId(null); setRenameValue(""); }
  async function deleteConversation() { if (!supabase || !deleteId) return; const { error: deleteError } = await supabase.from("conversations").delete().eq("id", deleteId); if (deleteError) { setError(deleteError.message); return; } if (deleteId === conversationId) { setConversationId(crypto.randomUUID()); setMessages([]); } setHistory(items => items.filter(item => item.id !== deleteId)); setDeleteId(null); }
  function historyGroup(date?: string) { const time = date ? new Date(date).getTime() : 0; const days = Math.floor((Date.now() - time) / 86400000); return days < 1 ? "Hoy" : days < 2 ? "Ayer" : days < 7 ? "Últimos 7 días" : "Anteriores"; }
  async function loadHistory() { if (!supabase) return; const uid=(await supabase.auth.getUser()).data.user?.id; const cacheKey=uid ? `ainslup-history-${uid}` : "ainslup-history-cache"; let cached: unknown=null; try { cached=JSON.parse(sessionStorage.getItem(cacheKey)||"null"); if (Array.isArray(cached)) setHistory(cached as HistoryItem[]); } catch {} const modern = await supabase.from("conversations").select("id,title,data,pinned,archived,updated_at").order("pinned", { ascending: false }).order("updated_at", { ascending: false }).limit(50); if (!modern.error && modern.data) { setHistory(modern.data as HistoryItem[]); try { sessionStorage.setItem(cacheKey,JSON.stringify(modern.data)); } catch {} return; } const legacy = await supabase.from("conversations").select("id,title,data,updated_at").order("updated_at", { ascending: false }).limit(50); if (!legacy.error && legacy.data) { const safe=legacy.data.map(item => ({ ...item, pinned: false, archived: false })) as HistoryItem[]; setHistory(safe); try { sessionStorage.setItem(cacheKey,JSON.stringify(safe)); } catch {} return; } if (!Array.isArray(cached)) setError(legacy.error?.message || modern.error?.message || "No se pudo cargar el historial."); }
  async function revealAnswer(next: Message[], answer: string) { const words = answer.split(/(\s+)/); let shown = ""; for (const word of words) { shown += word; setMessages([...next, { role: "assistant", content: shown }]); await new Promise(resolve => setTimeout(resolve, word.trim() ? 24 : 0)); } const complete = [...next, { role: "assistant" as const, content: answer }]; setMessages(complete); await saveConversation(complete); loadHistory(); }
  function toggleVoice() { if (listening) { recognitionRef.current?.stop(); setListening(false); return; } const Voice = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition; if (!Voice) { setError("El reconocimiento de voz no está disponible en este navegador."); return; } const recognition = new Voice(); recognition.lang = voiceLanguage; recognition.continuous = false; recognition.interimResults = true; recognition.onresult = (event: any) => { const transcript = Array.from(event.results).map((result: any) => result[0].transcript).join(""); setText(transcript); }; recognition.onstart = () => setListening(true); recognition.onend = () => { setListening(false); recognitionRef.current = null; }; recognition.onerror = () => { setListening(false); recognitionRef.current = null; setError("No se pudo acceder al micrófono."); }; recognitionRef.current = recognition; recognition.start(); }
  function toggleSidebar() { setSidebarAnimating(true); setSidebarCollapsed(value => !value); window.setTimeout(() => setSidebarAnimating(false), 320); }
  async function streamAnswer(next: Message[], token: string, value: string) { const controller=new AbortController(); abortRef.current=controller; const r=await fetch(`${EDGE}/chat-stream`, { method:"POST", headers:{ Authorization:`Bearer ${token}`, "Content-Type":"application/json", Accept:"text/event-stream" }, body:JSON.stringify({ messages:next, xens_model:defaultModel, web_search:webSearchMode, stream:true, xens_stream:true }), signal:controller.signal }); if(!r.ok || !r.body) { const detail=await r.text().catch(()=>""); throw new Error(detail || "No se pudo iniciar la generación."); } const reader=r.body.getReader(); const decoder=new TextDecoder(); let buffer=""; let answer=""; setGenerationStatus("AINSLUP está escribiendo…"); const update=(part:string)=>{ answer+=part; setMessages([...next,{role:"assistant",content:answer}]); }; while(true){ const chunk=await reader.read(); if(chunk.done) break; buffer+=decoder.decode(chunk.value,{stream:true}); const events=buffer.split("\n"); buffer=events.pop()||""; for(const line of events){ const raw=line.trim(); if(!raw.startsWith("data:")) continue; const payload=raw.slice(5).trim(); if(payload==="[DONE]") continue; try{ const json=JSON.parse(payload); const delta=json.choices?.[0]?.delta?.content ?? json.choices?.[0]?.message?.content ?? ""; if(delta) update(String(delta)); }catch{} } } if(!answer) throw new Error("La respuesta llegó vacía."); const complete=[...next,{role:"assistant" as const,content:answer}]; setMessages(complete); await saveConversation(complete); loadHistory(); abortRef.current=null; return answer; }
  function cancelGeneration(){ abortRef.current?.abort(); abortRef.current=null; setGenerationStatus("Generación cancelada"); setBusy(false); }
  async function send(e?: FormEvent) { e?.preventDefault(); const value = text.trim(); if ((!value && !file) || busy || !supabase) return; setText(""); setError(""); let userContent: any = value; let attachment: Message["attachment"]; if (file) { attachment = { name: file.name, type: file.type }; if (file.type.startsWith("image/")) { const data = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); }); userContent = [{ type: "text", text: value || `Analiza esta imagen: ${file.name}` }, { type: "image_url", image_url: { url: data } }]; } else { const content = await file.text(); userContent = `${value ? value + "\n\n" : ""}Contenido del archivo ${file.name}:\n${content.slice(0, 50000)}`; } setFile(null); } const next = [...messages, { role: "user" as const, content: userContent, attachment }]; setMessages(next); setBusy(true); try { const token = (await supabase!.auth.getSession()).data.session?.access_token; if (!token) throw new Error("Sesión expirada. Inicia sesión de nuevo."); setRetryText(value); setRetryBase(next); setGenerationStatus("Conectando con AINSLUP…"); await streamAnswer(next, token, value); } catch (err) { if (err instanceof DOMException && err.name === "AbortError") { setError("Generación detenida."); } else { setError(err instanceof Error ? err.message : "Error de conexión"); } } finally { abortRef.current=null; setBusy(false); setGenerationStatus(""); } }
