  function continueFrom(content: string) { setText(`Continúa desde esta respuesta y desarrolla el siguiente paso:

${content}`); document.querySelector(".composer textarea")?.scrollIntoView({ behavior: "smooth", block: "center" }); }
  function regenerateResponse(index: number) { const base=messages.slice(0,index); const last=base[base.length-1]; if (!last || last.role!=="user" || typeof last.content!=="string") { setError("No se puede regenerar esta respuesta con el contenido actual."); return; } setMessages(base); setText(last.content); window.setTimeout(()=>(document.querySelector("form.composer") as HTMLFormElement | null)?.requestSubmit(),50); }
  async function startCheckout(plan: string) { if(!supabase) return; setPurchasePlan(plan); setError(""); try { const token=(await supabase.auth.getSession()).data.session?.access_token; if(!token) throw new Error("Sesión expirada. Inicia sesión de nuevo."); const r=await fetch(`${EDGE}/checkout`,{method:"POST",headers:{Authorization:`Bearer ${token}`,"Content-Type":"application/json"},body:JSON.stringify({plan,return_url:`${window.location.origin}/app`,cancel_url:`${window.location.origin}/app`})}); const data=await r.json().catch(()=>({})); if(!r.ok) throw new Error(data.error||"No se pudo iniciar el pago."); window.location.href=data.approval_url; } catch(err) { setError(err instanceof Error?err.message:"No se pudo iniciar el pago."); setPurchasePlan(""); } }
